/* Made by scripts/kit-files.mjs from kit/ (npm run kit:files). Do not edit by hand. */
/* The builder kit's files, as text, for Export for code (kitExport.ts). */
export const KIT_VERSION = "1.0.0";
export const KIT_FILES: Record<string, string> = {
  "BUILDER-CONTRACT.md": "# The builder contract\n\nA site built to this contract can be opened in J's Polio builder and restyled, part by part,\nwithout touching its code. The builder reads `builder.json` first, finds every part by its\n`data-hook`, edits the tokens, and sends the design back as one stylesheet, `style-layer.css`,\nkeyed by `[data-hook=\"...\"]`. The code keeps working because it never depends on anything the\ndesign changes.\n\n`npm run kit:check` enforces every rule marked **(checked)**. It fails the build on any break.\n\n## 1. Every visible element has a hook\n\n- **(checked)** Every element inside `<body>`, `<body>` itself and layout containers included\n  (`header`, `main`, `section`, `div`, `ul`, `li`, `span`, `label`...), has a `data-hook`. Only\n  `<script>`, `<br>` and `<wbr>` go without.\n- **(checked) Unique on its page.** A hook names one element on a page. Parts a script repeats are\n  written once inside a `<template>` (see 4); every copy keeps the same hooks.\n- **(checked) Meaningful and stable.** Lower-case words joined by dashes, naming what the part is:\n  `signup-modal`, `contact-form`, `list-item-name`. Not `div-3`, `box`, `wrapper`. Renaming a hook\n  is a breaking change for the design: change the markup, scripts and `hooks.json` together.\n- **(checked) One kind per hook.** A hook used on several pages (`site-header`, `page-title`,\n  `nav-home`) is the same element kind everywhere, so one design rule fits all of them.\n- Naming habits that help the builder group parts: `<area>-<part>` (`home-hero`, `hero-button`),\n  buttons end in `-button`, inputs in `-input`, error lines in `-error`, the page body is\n  `page-<name>`.\n\n## 2. Styles only through tokens and hook-keyed rules\n\n- **(checked) No inline styles.** No `style=\"...\"` in markup, no `<style>` blocks in pages, and no\n  `el.style.x = ...`, `cssText` or `setAttribute('style', ...)` in scripts. A script that works out\n  a position or size sets a CSS variable instead: `el.style.setProperty('--marker-left', x + 'px')`,\n  and the stylesheet uses `left: var(--marker-left)`.\n- **(checked) Colours are tokens.** Every colour is a named variable in `tokens.css`\n  (`--color-accent: #2f6fde`). Every other stylesheet, and every script, uses `var(--color-...)`.\n  Hex, `rgb()`, `hsl()`, `oklch()` and named colours anywhere else fail. A script that needs a\n  colour (a chart) reads the token: `getComputedStyle(document.documentElement).getPropertyValue('--color-accent')`.\n  Where there is no styled page to read from (a test in Node, a picture drawn as a data URL), set\n  `tokensModule` in `builder.json` (for example `web/tokens.js`): `npm run kit:hooks` writes every\n  token's value there as `export const TOKENS = {...}`, and `kit:check` fails if it is stale.\n  Import colours from it; never type them.\n- **(checked) Every `var(--x)` exists**: a token in `tokens.css` (or `style-layer.css`), or a\n  run-time variable declared with its default on the rule that uses it\n  (`[data-hook=\"trade-marker\"] { --marker-left: 0; left: var(--marker-left); }`).\n- **(checked) Rules are keyed by hook.** Selectors use `[data-hook=\"...\"]` (or `^=` / `$=` for a\n  family, like `[data-hook$=\"-button\"]`), element names, `:root`, `html`, `body` or attributes.\n  No class or id selectors: classes and ids are free for nothing and so never break.\n- Sizes, spacing, fonts and radii should be tokens too (`--space-3`, `--radius`); this is not\n  checked, but the builder can only edit what has a name.\n- **Script settings are tokens.** A number, colour or piece of text a script uses for how a part\n  looks or reads (a chart's line width, a flash's duration, a candle count, a button's label, a\n  countdown's warning threshold) is a token in `tokens.css` (`--chart-line-width: 2`,\n  `--flash-ms: 400`, `--label-trade: \"Trade\"`), read with `getComputedStyle` or imported from the\n  `tokensModule` (`TOKENS['--flash-ms']`), never typed into the script. The builder lists each\n  part's tokens, with the ones its scripts read, as its settings, and sends edits back as token\n  changes. Values that decide the rules or money (fees, payouts, limits) stay in the code.\n- Scripts show and hide parts with the `hidden` attribute; `base.css` keeps\n  `[hidden] { display: none !important; }` so a design rule never shows a hidden part.\n\n## 3. Stylesheet order\n\n- **(checked)** Every page loads `tokens.css` first and `style-layer.css` last. In between:\n  `base.css` (what the site needs to work and look decent).\n- `style-layer.css` ships empty. It belongs to the design: code changes never edit it. It may\n  redefine any token and add any `[data-hook]` rule; it wins because it loads last.\n\n## 4. Script-built elements are declared\n\n- **(checked)** Scripts never build markup: no `createElement`, `innerHTML =`, `outerHTML =` or\n  `insertAdjacentHTML`. Anything a script adds is declared in the page as\n  `<template data-hook=\"template-<name>\">` holding exactly one element, every part of it hooked,\n  and cloned with `fromTemplate('template-<name>')`. The builder sees and styles it like any part.\n- **(checked)** Scripts reach elements only by hook, through the helpers in `js/hooks.js`\n  (`hook`, `hooks`, `fromTemplate`, `part`) or a literal `[data-hook=\"...\"]` selector. The hook\n  name is a plain string. `fill(copy, { 'hook-name': value })` counts too: each quoted key is a\n  hook the call writes, and an element held in a variable (`const a = hook('x'); a.href = ...`) is\n  followed to the end of its function. When a script must build a name (`nav-${page}`), the same line carries a\n  comment listing every name it can be: `// hooks: nav-{home,about,list}`.\n- **(checked)** Every hook a script uses exists on a page; every hook a stylesheet names exists.\n- **(checked)** No inline `<script>` code; scripts live in `.js` files.\n\n## 5. Preview screens\n\n- Every page works frozen and in a chosen state at `page.html?still=1&screen=<name>`:\n  `still=1` stops animations and uses sample data and fixed dates; `screen` picks a state (a modal\n  open, a form with errors, an empty list). Pages declare their screens in their script with\n  `screens({ name: () => ..., ... })`; the first one is the default.\n- **(checked)** Every screen listed in `builder.json` is declared by its page's scripts.\n- A part a script draws into (a chart, a canvas) is empty when the builder imports the page without\n  its scripts. `builder.json` `preview.stills` names such parts by hook, with the screen to take them\n  on (`[{ \"hook\": \"chart\", \"screen\": \"tv-idle\" }]`): the builder opens the preview page at that\n  screen from the repository's own files (no network), takes a picture of that part alone, and shows\n  it as the part's picture on the board, so a design is made around real content.\n- `preview.html` shows every screen from `builder.json` side by side. `gallery.html` shows every\n  reusable part on one page (buttons, fields, cards, list rows), using the same hooks as the real\n  pages, so one rule can be judged everywhere at once.\n\n## 6. Links\n\n- **(checked)** A control is a link (`<a href>`) only if it leads somewhere; an action is a\n  `<button>`. `href=\"#\"`, an empty href or `javascript:` fail unless a script sets the href.\n- **(checked)** A link leaves the site only to a host in `builder.json` `links.allowHosts`, and\n  never matches a pattern in `links.block`. The defaults carry J's rules: pump.fun allowed;\n  DexScreener allowed but never a link to a specific contract address (embeds are fine); no X\n  (Twitter) profile links.\n\n## 7. The map and the manifest\n\n- `builder.json` (repo root) is what the builder reads first: kit version, pages, and the paths to\n  `hooks.json`, `tokens.css`, `style-layer.css`, the preview page and its screens, and the gallery.\n- `hooks.json` is generated (`npm run kit:hooks`) and committed. For every hook: its pages,\n  element, the hook around it, whether a script builds it and from which template, the tokens its\n  rules use, and every code reference (file, line, function, and whether the code reads, writes or\n  listens on it). It also lists each page's stylesheets and scripts and each token with its\n  default and the hooks that use it.\n- **(checked)** `hooks.json` matches the code. If it is stale, `kit:check` fails: run\n  `npm run kit:hooks` and commit the result with the change.\n",
  "PIPELINE.md": "# Pipeline: a new site, through the builder, either way round\n\nA site made from this kit is worked on in two places: in code, by code chats, and in J's Polio\nbuilder, by J. This page says who does each step, with what command or button, and what proves it\nworked. It covers both starts (builder first, code first) and every change after that.\n\n## Who owns what\n\n| Who | Owns | Never touches |\n| --- | --- | --- |\n| **J** | the look: designs in the builder, decides what ships | code |\n| **The builder** (Polio) | `style-layer.css`, the values in `tokens.css`, the `styleAssets` folder if `builder.json` names one | pages, scripts, `base.css`, hook names |\n| **A code chat** | pages, scripts, `base.css`, new tokens, `builder.json`, preview screens | `style-layer.css` |\n| **A merge chat** | merging the builder's style branches (a code chat whose only job is that) | anything but the merge |\n\nGenerated, never edited by hand: `hooks.json` (and `tokens.js` if `builder.json` names a\n`tokensModule`). Run `npm run kit:hooks` to rewrite them.\n\nBecause the two sides own different files, a design branch and a code branch never conflict. The\nchecks below catch the one way they can still break each other: code dropping a hook the design\nstyles.\n\n## The checks\n\n| Command | Proves | Runs |\n| --- | --- | --- |\n| `npm run kit:check` | every page, stylesheet and script keeps the contract; `hooks.json` is current | every push (GitHub Actions) |\n| `npm test` | the kit's own tests | every push |\n| `npm run kit:diff -- --base origin/main` | a code change drops no hook the base had | every pull request |\n| `npm run kit:diff -- --base origin/main --style-only` | a design change touches only the style layer and token values, and changes no hook | every pull request from a `style/...` branch |\n| `preview.html?still=1&screen=<name>` | each state of each page renders, still, with sample data | by eye, and in the builder |\n\nThe workflow in `.github/workflows/kit-check.yml` runs all of these by itself.\n\n## Route 1: builder first\n\nJ designs the site in the builder; the builder hands a code chat a repo that is already\nbuilder-ready.\n\n| # | Step | Who | Command or button | Check that proves it worked |\n| --- | --- | --- | --- | --- |\n| 1 | Design the pages | J | Builder: **Make a new one** | the pages look right in the builder |\n| 2 | Export a builder-ready repo: this kit, `builder.json` listing the pages, every element with a `data-hook`, `tokens.css`, an empty `style-layer.css`, `hooks.json`, `CLAUDE.md`, and a preview screen per page | the builder | Builder: **Export for code** (missing, see below) | in the export, `npm run kit:check` passes |\n| 3 | Put it on GitHub | J (or the builder) | Builder: **Go live** to a new repo | the kit-check run on GitHub is green |\n| 4 | Add the logic | a code chat | paste the first prompt below; it works on a branch and opens a pull request | CI green: `kit:check`, `npm test`, `kit:diff` |\n| 5 | Merge | the code chat | merge the pull request | CI green on the default branch |\n\nFrom here, follow **Later changes**.\n\n## Route 2: code first\n\nA code chat builds the site from the starter; J designs it afterwards.\n\n| # | Step | Who | Command or button | Check that proves it worked |\n| --- | --- | --- | --- | --- |\n| 1 | Make the repo from the kit | a code chat | `npm run kit:new -- ../<site> --name \"<Site name>\"` from this kit, then `git init`, commit, push as a new repo | it prints `kit:new made ... kit:check passed`; the first CI run is green |\n| 2 | Build the site | the code chat | edit pages and scripts; add each state to `builder.json` `preview.screens`; `npm run kit:hooks` | CI green on every pull request; every screen shows at `preview.html?still=1&screen=<name>` |\n| 3 | Bring it into the builder | J | Builder: **Bring one in**, pick the repo; the builder reads `builder.json` | the builder lists every page, names parts by their hooks, shows every preview screen (missing, see below) |\n| 4 | Redesign | J | the builder; it writes only rules keyed by `[data-hook=\"...\"]` and token values | the builder's preview of each screen looks right |\n| 5 | Send the design back | the builder | Builder: **Send design** pushes a `style/<name>` branch and opens a pull request (missing, see below) | CI green, including `kit:diff --style-only` |\n| 6 | Merge the design | a merge chat (or the code chat) | merge the `style/...` pull request | CI green on the default branch; `gallery.html` matches the builder |\n\n## Later changes, either direction\n\n| Change | Who | Steps | Check |\n| --- | --- | --- | --- |\n| New logic or a new page | a code chat | branch; change; `npm run kit:hooks`; `npm run kit:check`; `npm run kit:diff -- --base origin/main`; pull request; merge | CI green |\n| A hook must go or be renamed | a code chat | as above with `--allow-removed`, and say in the pull request which hooks went, so J can move their style | CI green; J sees the note |\n| J deleted a part in the builder | a code chat, from the builder's `design/` branch | delete the element and every code reference to it; `npm run kit:diff -- --base <default branch>` passes because `design/HOOK-CHANGES.json` lists the hook as removed (any hook not listed there still fails) | CI green; the hook is gone |\n| Build from a design | a code chat, from a `design/` branch carrying `design/record.json` | build each part from the record (hooks kept, token values into tokens), then a look-only capture and `npm run kit:record-diff -- design/record.json <capture>` | record-diff lists no part; kit:check and kit:diff pass |\n| A new look | J, then the builder | the builder re-reads `builder.json` and `hooks.json` from the default branch first (so it sees new pages and hooks); J designs; **Send design** | `kit:diff --style-only` green |\n| Both at once | both | nothing special: each side touches only its own files. Whoever merges second re-runs CI on the merged result | CI green after both merges |\n\nIf a style rule names a hook that a code change removed, `kit:check` fails on whichever pull\nrequest merges second (\"rule for hook ..., which no page has\"). The chat merging it fixes it: put\nthe hook back, or ask J to move the style.\n\n## New-site checklist\n\n- [ ] Pick the route: builder first (J has a design) or code first (logic first).\n- [ ] Repo made from the kit (`kit:new`) or by the builder's export; `kit:check` passes.\n- [ ] `builder.json`: the site's name, every page, a preview screen for every state (empty,\n      error, loading, pop-ups), `links.allowHosts` and `links.block` as the project allows.\n- [ ] The GitHub workflow is at `.github/workflows/kit-check.yml` and its first run is green.\n- [ ] Branch protection on the default branch requires the kit-check run (J, in GitHub settings).\n- [ ] `CLAUDE.md` has the project's own rules added under the kit's (networks, money, keys).\n- [ ] `preview.html` and `gallery.html` show every screen; `?still=1` gives the same picture twice.\n- [ ] `style-layer.css` is empty until the builder's first design arrives.\n\n## First prompt for a new code chat\n\nPaste this as the first message in a new code chat, filling the two lines in angle brackets.\n\n```\nYou are working on <site name>, a website J designs in the Polio builder. It must stay\nbuilder-ready: read CLAUDE.md, AGENTS.md, BUILDER-CONTRACT.md and PIPELINE.md first, and follow them.\n<If the repo is empty: run `npm run kit:new` from the builder kit (sparkygogo77-spec/PST, folder kit/)\nto start it, and push that as the first commit.>\nThe job: <what the site does, its pages, and each state a page can be in>.\nRules:\n- Every element gets a data-hook; never rename or drop one the design may style\n  (kit:diff tells you); never edit style-layer.css; colours only in tokens.css.\n- Add every page state to builder.json preview.screens so the builder can show it.\n- Work on a branch, one pull request per job. Before you call it done, run\n  npm run kit:hooks, npm run kit:check, npm test and npm run kit:diff -- --base origin/main,\n  and paste their summary lines.\n- Pull requests from style/... branches are J's design from the builder: merge them once CI is green.\n- Keep messages to J short and simple; ask only for real choices (money, keys, accounts, rules).\n```\n\n## Builder (Polio) pieces still missing\n\nChecked against the Polio repo on 2026-10-02. Today the builder imports a site by measuring it and\nrebuilding it as its own parts, and its export strips every `data-*` attribute, so none of the\ncontract survives a round trip yet.\n\n1. **Export for code** (route 1, step 2): export a repo with this kit's files, `builder.json`, a\n   `data-hook` on every element (named for a person, see `AGENTS.md`), `tokens.css` from the\n   colour roles, an empty `style-layer.css`, `base.css`, `hooks.json` (run `kit-check --write`),\n   `CLAUDE.md`, and a preview screen per page. Today `exportSite.ts` removes `data-*` attributes and\n   writes one stylesheet; `POLIO.md` should still go along.\n2. **Import through `builder.json`** (route 2, step 3): when a repo has `builder.json`, read its\n   pages, `hooks.json` and `tokens.css`, name parts by their hooks, and load the preview screens\n   (`preview.html?still=1&screen=<name>`) instead of measuring and rebuilding.\n3. **Send design** (route 2, step 5): write only `style-layer.css` (rules keyed by\n   `[data-hook=\"...\"]`) and changed token values, push them to a new `style/<name>` branch and\n   open a pull request. Today **Go live** pushes the whole site to the stored branch and deploys.\n4. **Re-read before each design round**: fetch `builder.json` and `hooks.json` from the default\n   branch, show hooks added or removed since the last round, and flag style rules for hooks that\n   no longer exist.\n5. **Link rules**: links the builder adds follow `builder.json` `links.allowHosts` and\n   `links.block`.\n6. **Where the kit comes from**: the builder needs these kit files to export (1). Either copy\n   `kit/` into Polio, or move the kit to its own repo that both read (the cleaner choice once\n   a second site exists).\n",
  "AGENTS.md": "# Working in a builder-ready repo\n\nThis repo's pages are edited in two places: here, in code, and in J's Polio builder, which\nrestyles them. The builder reads `builder.json`, then `hooks.json`, and sends its design back as\n`style-layer.css`. Your job is to change how the site works without ever breaking how it can be\ndesigned. The rules are in `BUILDER-CONTRACT.md`; `npm run kit:check` enforces them.\n\n## Where things go\n\n| What | Where |\n| --- | --- |\n| The manifest the builder reads first | `builder.json` |\n| Pages | the paths listed in `builder.json` `pages` |\n| Colours, fonts, sizes, spacing | `tokens.css` (`:root { --name: value }`) |\n| What the site needs to work and look decent | `base.css`, rules keyed by `[data-hook=\"...\"]` |\n| The design | `style-layer.css` (empty; never edited by code changes) |\n| Hook helpers, preview states | `js/hooks.js` (`hook`, `hooks`, `fromTemplate`, `part`, `screens`) |\n| Generated map of every hook | `hooks.json` (`npm run kit:hooks`; never edited by hand) |\n| Every screen frozen side by side | `preview.html` (screens listed in `builder.json`) |\n| Every reusable part on one page | `gallery.html` |\n\n## Adding or changing a page\n\n1. Copy an existing page so the head is right: `tokens.css` first, `base.css`, `style-layer.css`\n   last, one `<script type=\"module\" src=\"js/<page>.js\">`.\n2. Give `<body>` the hook `page-<name>` and every element inside a hook (see naming below).\n3. Anything a script repeats or adds goes in a `<template data-hook=\"template-<thing>\">` holding\n   one element; clone it with `fromTemplate` and fill its parts with `part(copy, 'hook')`.\n4. In the page's script, declare its states: `screens({ '<name>': () => {}, '<name>-empty': ... })`.\n5. Add the page to `builder.json` `pages`, and each state to `preview.screens`.\n6. Style it in `base.css` with `[data-hook=\"...\"]` rules and `var(--token)` values. Need a new\n   colour? Add a token to `tokens.css` first.\n7. `npm run kit:hooks && npm run kit:check`, then commit `hooks.json` with the change.\n\n## Naming hooks\n\n- Lower-case words joined by dashes that say what the part is: `contact-form`, `email-error`,\n  `list-item-name`. The builder shows these names to J; write them for a person.\n- `<area>-<part>`: `home-hero`, `hero-button`, `modal-title`.\n- Endings the builder groups by: `-button`, `-input`, `-field`, `-error`, `-title`, `-text`,\n  `-link`, `-list`, `-item`. Templates start with `template-`. Page bodies start with `page-`.\n- A part that appears on several pages keeps one hook and one element kind everywhere.\n- Renaming a hook drops the design's rules for it. Don't rename without a reason; when you must,\n  say so in the pull request so J can move the style.\n\n## Scripts\n\n- Reach elements only with the helpers or a literal `[data-hook=\"...\"]` selector. If a name is\n  built at run time, put `// hooks: name-{a,b,c}` on that line listing every possibility.\n- Show and hide with the `hidden` attribute. Never set inline styles; to pass a computed number\n  to CSS, set a variable: `el.style.setProperty('--bar-width', pct + '%')`.\n- Colours, numbers and text a script needs for how things look or read (charts, canvas, durations,\n  labels) come from tokens via `getComputedStyle` or the `tokensModule`; never type them into a\n  script. Rules and money stay in the code.\n- `?still=1` must give a stable picture: no animation, fixed sample data and dates.\n\n## Links\n\nAn action is a `<button>`; a link goes somewhere. Outside links only to hosts in\n`builder.json` `links.allowHosts`, never matching `links.block` (by default: pump.fun allowed;\nDexScreener allowed but never to a specific contract address; no X profile links).\n\n## Before you push\n\n```\nnpm run kit:hooks\nnpm run kit:check\nnpm test\nnpm run kit:diff -- --base origin/main\n```\n\nAll four must pass. Never weaken the check, add an ignore, or edit `hooks.json` by hand to get\ngreen; fix the page instead.\n\n## Building from a design record\n\nWhen a branch carries `design/record.json` (written by the builder or the capturer, format in\n`DESIGN-RECORD.md`), build from it:\n\n1. Each part keeps its `hook` as its `data-hook`, exactly; a part without one gets a hook from its\n   `label`.\n2. Each value a part lists under `tokens` goes into `tokens.css` under that token name (and\n   `tokens.js` via `npm run kit:hooks`); styles and scripts use the token.\n3. `states` become `:hover` / `:active` rules and the `hidden` attribute; `breakpoints` become media\n   queries.\n4. Check it: take a look-only capture of the built page and run\n   `npm run kit:record-diff -- design/record.json <capture>.json --page <file>`. Fix every part it\n   lists, then `kit:check` and `kit:diff`.\n\n",
  "CLAUDE.md": "# Claude / agent entry point\n\nThis repo is built to the **builder contract**: J's Polio builder reads and restyles every part of\nthe site, so every change you make must keep it readable. Read `AGENTS.md` (how to work here) and\n`BUILDER-CONTRACT.md` (the rules) before touching any page, stylesheet or script.\n\nThe short version:\n\n- Every element in `<body>` gets a unique, meaningful `data-hook`. Layout containers too.\n- No inline styles, no `<style>` blocks, no class or id selectors, no colours outside `tokens.css`.\n- Numbers, colours and text a script uses for how things look or read are tokens in `tokens.css`\n  (read with `getComputedStyle` or from `tokens.js`), never literals: the builder edits them.\n- Scripts find elements only by hook (`hook('name')`) and build nothing by hand: repeated parts\n  come from `<template data-hook=\"template-...\">`.\n- `tokens.css` loads first, `style-layer.css` loads last. Never edit `style-layer.css`; it is the\n  design's file.\n- New page? Add it to `builder.json`, with at least one preview screen.\n- Building from a design? Build from `design/record.json` (`DESIGN-RECORD.md`): keep each part's\n  hook exactly, put every value it marks as a token in `tokens.css`/`tokens.js`, then check the\n  build with a look-only capture and `npm run kit:record-diff -- design/record.json <capture>`.\n\nCommands:\n\n```\nnpm run kit:hooks   # rewrite hooks.json from the code (run after any page, CSS or script edit)\nnpm run kit:check   # the contract check; must pass before you push\nnpm run kit:diff -- --base origin/main   # no hook the design uses was dropped\nnpm test            # the kit's own tests\n```\n\n`kit:check` and `kit:diff` passing are part of \"done\". `PIPELINE.md` says how this repo moves\nbetween code and the builder; pull requests from `style/...` branches are J's design. If one fails, fix the code, not the check.\n",
  "RETROFIT.md": "# Bringing an existing repo up to the contract\n\nThe steps below work for any static or lightly scripted site. The worked example is PonsStars\n(`sparkygogo77-spec/PST`, folder `web/`), checked on 2 October 2026 against the merged design\nreadiness work (pull request #6).\n\n## Steps\n\n1. **Copy the kit in.** Into the repo (root, or the folder that serves the site):\n   `tools/kit-check.mjs`, `BUILDER-CONTRACT.md`, the `kit:check`, `kit:hooks` scripts from\n   `package.json`, and `.github/workflows/kit-check.yml` (set its working directory if the site is\n   in a subfolder). Merge `CLAUDE.md` and `AGENTS.md` into the repo's own, keeping the repo's other\n   rules.\n2. **Write `builder.json`** at the root, pointing at what exists today. If the scripts already reach\n   elements through helpers, name them in `scripts.hookCalls` (helper name: which argument is the\n   hook) and put the helper file in `scripts.helperFiles`, so nothing needs renaming yet.\n3. **Run it once with `--write`** (`node tools/kit-check.mjs builder.json --write`) and sort the\n   problem list by kind. Fix in this order, running the check after each:\n   1. hooks (missing, duplicate, vague names, one kind per hook);\n   2. tokens: move every `:root` variable into `tokens.css`, load it first, and turn each colour\n      the check lists into a token;\n   3. stylesheet order: `style-layer.css` last, empty;\n   4. inline styles from scripts: pass numbers through CSS variables instead;\n   5. markup built by scripts: move it into `<template>`s;\n   6. run-time hook names: add `// hooks:` comments;\n   7. links and inline scripts;\n   8. preview screens: each page answers `?still=1&screen=<name>`; list them in `builder.json`.\n4. **Commit `hooks.json`** once the check passes, and keep CI running `kit:check`.\n\nDo it in small pull requests, one kind of fix each, with the site's own tests run every time: the\ncheck proves the builder can read the site, not that the site still works.\n\n## Worked example: PonsStars\n\n**Status: done** (2 October 2026). `kit:check` passes on PST's `web/` with no problems; the\nmanifest is PST's `builder.json` and `server/test/kit-check.test.ts` keeps it that way. What it\ntook is below; the table was the starting point.\n\nManifest used for the trial run (at the repo root, nothing renamed):\n\n```json\n{\n  \"kit\": \"1.0.0\",\n  \"pages\": [{ \"file\": \"web/index.html\" }, { \"file\": \"web/profile.html\" }, { \"file\": \"web/match.html\" },\n            { \"file\": \"web/leaderboard.html\" }, { \"file\": \"web/library.html\" }],\n  \"hooks\": \"web/hooks.kit.json\",\n  \"tokens\": \"web/base.css\",\n  \"styleLayer\": \"web/style-layer.css\",\n  \"preview\": { \"page\": \"web/preview.html\", \"screens\": [] },\n  \"gallery\": \"web/library.html\",\n  \"scripts\": {\n    \"hookCalls\": { \"$\": 0, \"setText\": 0, \"show\": 0, \"fromTemplate\": 0, \"part\": 1, \"drop\": 1 },\n    \"helperFiles\": [\"web/dom.js\"]\n  },\n  \"links\": { \"allowHosts\": [\"pump.fun\", \"dexscreener.com\"] }\n}\n```\n\n**Already there.** PST mapped cleanly: 639 hooks, with no missing hook, duplicate hook, bad name or\nmixed element kind on any page. `style-layer.css` already loads last and is empty, repeated parts\nalready come from `<template data-hook=\"template-...\">`, scripts already reach elements only\nthrough `web/dom.js`, and most run-time names already carry `// hooks:` comments. PST also has its\nown generator (`cd server && npm run hooks`, writing `web/hooks.json` and checked by\n`server/test/hooks-map.test.ts`); the kit's map has the same shape of information, so the two can\nrun side by side (`web/hooks.kit.json`) until PST switches over.\n\n**What the check reported (71 problems), and the fix for each:**\n\n| Count | Problem | Fix in PST |\n| ---: | --- | --- |\n| 17 | Colours in scripts (`avatars.js` 13, `overlay.js` 4) | Add tokens (`--avatar-*`, `--overlay-*`) and read them with `getComputedStyle` |\n| 12 | Scripts set inline styles (`app.js` trade markers, `preview.js` frame sizing) | Set CSS variables (`--marker-left`, `--marker-top`) and use them in `base.css` |\n| 11 | Colours in `base.css` outside a variable (`#fff`, `rgba(...)`, `#2563eb`...) | Create `web/tokens.css` with the `--pons-*` variables plus these colours; load it first |\n| 11 | Scripts build markup (`app.js` 7, `preview.js` 4) | Declare each in a `<template>` and clone it |\n| 11 | Links with `href=\"#\"` that a script fills through a variable | Set the href through a hook helper call (`part(row, 'history-opponent-link').href = ...`) so the map sees the write |\n| 5 | Inline `<script type=\"module\">` in pages | Move each to `web/<page>.js` |\n| 2 | Run-time hook names without a comment (`app.js:62`, `tour.js:202`) | Add `// hooks: ...` lists |\n| 1 | `base.css` is first, not a tokens file | Follows from the `tokens.css` split |\n| 1 | A link to a chart library's site | Gone: the site now draws its own charts (`web/pons-chart.js`), so no credit link is needed |\n\n**Preview screens.** PST's pages take `?preview=<screen>` and `preview.html` takes\n`?still=1&screen=<name>`. To meet the contract, each page also accepts `?still=1&screen=<name>`\n(a rename of its existing `preview` parameter), and the screen names go into `builder.json`.\n\n**Order for PST.** 1) `tokens.css` split and colour tokens; 2) inline styles to CSS variables;\n3) templates for script-built markup; 4) links, inline scripts, `// hooks:` comments;\n5) screens in `builder.json`, then switch `server/test/hooks-map.test.ts` to run `kit:check`.\nSteps 1 and 2 touch `web/`, so they wait until no other thread is changing it.\n",
  "tools/kit-check.mjs": "#!/usr/bin/env node\n// kit-check: keeps a site readable and editable by the Polio builder (see BUILDER-CONTRACT.md).\n//\n//   node tools/kit-check.mjs [path/to/builder.json]           check; exit 1 on any problem\n//   node tools/kit-check.mjs [path/to/builder.json] --write   also rewrite hooks.json first\n//\n// It reads builder.json, then every page it lists (plus the preview and gallery pages), the\n// stylesheets they load and the scripts they load (following relative imports). It writes the\n// hooks map: every data-hook with its pages, element, the hook around it, whether a script builds\n// it from a <template>, the tokens it uses and every code reference (file, line, function).\n// No dependencies: plain Node 18+.\nimport { existsSync, readFileSync, writeFileSync } from 'node:fs';\nimport { dirname, join, relative, resolve } from 'node:path';\n\n// ------------------------------------------------------------------ small helpers\n\nconst lineAt = (text, index) => text.slice(0, index).split('\\n').length;\nconst sortObj = (o) => Object.fromEntries(Object.entries(o).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)));\nconst HOOK_NAME = /^[a-z][a-z0-9]*(-[a-z0-9]+)*$/;\nconst VAGUE = /^(div|span|el|element|item|box|wrap|wrapper|container|block|section|hook|thing|x)(-?\\d+)?$/;\nconst NO_HOOK = new Set(['script', 'br', 'wbr']);\nconst VOID = new Set(['area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'source', 'track', 'wbr']);\nconst COLOR = /#[0-9a-fA-F]{3,8}\\b|\\b(?:rgba?|hsla?|hwb|lab|lch|oklab|oklch|color)\\(|\\b(?:white|black|red|green|blue|yellow|orange|purple|pink|gray|grey|silver|navy|teal|maroon|olive|lime|aqua|cyan|magenta|fuchsia|gold|crimson|indigo|violet|brown|tan|beige)\\b/;\n\nexport function expandBraces(s) {\n  const m = /\\{([^{}]*)\\}/.exec(s);\n  if (!m) return [s];\n  return m[1].split(',').flatMap((alt) => expandBraces(s.slice(0, m.index) + alt.trim() + s.slice(m.index + m[0].length)));\n}\n\n// ------------------------------------------------------------------ HTML\n\nfunction parseAttrs(s) {\n  const out = {};\n  for (const m of s.matchAll(/([^\\s=>/]+)(?:\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+)))?/g)) out[m[1].toLowerCase()] = m[2] ?? m[3] ?? m[4] ?? '';\n  return out;\n}\n\n/** A small reader for hand-written pages: each element with its line, parent, and whether it is in <body> or a <template>. */\nexport function parsePage(file, text) {\n  const page = { file, elements: [], scripts: [], styles: [], problems: [] };\n  const stack = [];\n  const tagRe = /<!--[\\s\\S]*?-->|<!doctype[^>]*>|<\\/?([a-zA-Z][a-zA-Z0-9-]*)((?:\\s+[^\\s=>/]+(?:\\s*=\\s*(?:\"[^\"]*\"|'[^']*'|[^\\s>]+))?)*)\\s*(\\/?)>/gi;\n  let m;\n  while ((m = tagRe.exec(text))) {\n    if (!m[1]) continue;\n    const tag = m[1].toLowerCase();\n    const line = lineAt(text, m.index);\n    if (m[0].startsWith('</')) {\n      const at = stack.map((e) => e.tag).lastIndexOf(tag);\n      if (at === -1) page.problems.push(`${file}:${line}: </${tag}> closes nothing`);\n      else stack.length = at;\n      continue;\n    }\n    const parent = stack.at(-1) ?? null;\n    const tpl = [...stack].reverse().find((e) => e.tag === 'template');\n    const el = { tag, attrs: parseAttrs(m[2] ?? ''), line, parent, inBody: tag === 'body' || stack.some((e) => e.tag === 'body'), template: tpl ? tpl.attrs['data-hook'] ?? '?' : null };\n    page.elements.push(el);\n    if (tag === 'script' || tag === 'style') {\n      const end = text.indexOf(`</${tag}>`, tagRe.lastIndex);\n      const body = text.slice(tagRe.lastIndex, end);\n      if (tag === 'script') page.scripts.push({ src: el.attrs.src, inline: body.trim() !== '', line, type: el.attrs.type });\n      else page.styles.push({ inline: true, line });\n      tagRe.lastIndex = end + tag.length + 3;\n      continue;\n    }\n    if (tag === 'link' && /\\bstylesheet\\b/.test(el.attrs.rel ?? '')) page.styles.push({ href: el.attrs.href, line });\n    if (!VOID.has(tag) && !m[3]) stack.push(el);\n  }\n  if (stack.length) page.problems.push(`${file}: <${stack.at(-1).tag}> at line ${stack.at(-1).line} is never closed`);\n  return page;\n}\n\nconst kindOf = (el) => (el.tag === 'input' ? `input[type=${(el.attrs.type ?? 'text').toLowerCase()}]` : el.tag);\nfunction parentHook(el) {\n  for (let e = el.parent; e; e = e.parent) if (e.attrs['data-hook']) return e.attrs['data-hook'];\n  return null;\n}\n\n// ------------------------------------------------------------------ CSS\n\nexport function cssRules(text) {\n  const clean = text.replace(/\\/\\*[\\s\\S]*?\\*\\//g, (c) => c.replace(/[^\\n]/g, ' '));\n  const out = [];\n  const re = /([^{}]+)\\{([^{}]*)\\}/g;\n  let m;\n  while ((m = re.exec(clean))) {\n    const lead = m[1].length - m[1].trimStart().length;\n    const declStart = m.index + m[1].length + 1;\n    const decls = [];\n    let off = 0;\n    for (const part of m[2].split(';')) {\n      const i = part.indexOf(':');\n      if (i > 0) decls.push({ prop: part.slice(0, i).trim(), value: part.slice(i + 1).trim(), line: lineAt(clean, declStart + off + (part.length - part.trimStart().length)) });\n      off += part.length + 1;\n    }\n    out.push({ line: lineAt(clean, m.index + lead), selector: m[1].trim().replace(/\\s+/g, ' '), decls });\n  }\n  return out;\n}\nconst selectorHooks = (sel) => [...sel.matchAll(/\\[data-hook=\"([^\"]+)\"\\]/g)].map((x) => x[1]);\n/** Hooks a selector reaches, prefix ([data-hook^=\"nav-\"]) and suffix ([data-hook$=\"-button\"]) matches included. */\nconst selectorReach = (sel, known) => {\n  const out = new Set(selectorHooks(sel));\n  for (const [, op, v] of sel.matchAll(/\\[data-hook([\\^$*])=\"([^\"]+)\"\\]/g)) {\n    for (const h of known) if ((op === '^' && h.startsWith(v)) || (op === '$' && h.endsWith(v)) || (op === '*' && h.includes(v))) out.add(h);\n  }\n  return [...out];\n};\nconst varsIn = (value) => [...value.matchAll(/var\\(\\s*(--[a-zA-Z0-9-]+)/g)].map((x) => x[1]);\n\n// ------------------------------------------------------------------ JS\n\n/** Function ranges in a script, found by following braces (strings, comments and templates skipped). */\nexport function functionRanges(text) {\n  const ranges = [];\n  const stack = []; // { kind: 'fn'|'block'|'tpl', name, start }\n  let mode = 'code';\n  const modes = [];\n  let last = 0; // start of the current statement head\n  for (let i = 0; i < text.length; i++) {\n    const c = text[i];\n    const n = text[i + 1];\n    if (mode === 'line') { if (c === '\\n') { mode = 'code'; last = i + 1; } continue; }\n    if (mode === 'block') { if (c === '*' && n === '/') { mode = 'code'; i++; last = i + 1; } continue; }\n    if (mode === \"'\" || mode === '\"') { if (c === '\\\\') i++; else if (c === mode || c === '\\n') mode = 'code'; continue; }\n    if (mode === '`') {\n      if (c === '\\\\') i++;\n      else if (c === '`') mode = modes.pop() ?? 'code';\n      else if (c === '$' && n === '{') { stack.push({ kind: 'tpl' }); modes.push('`'); mode = 'code'; i++; }\n      continue;\n    }\n    if (c === '/' && n === '/') { mode = 'line'; i++; continue; }\n    if (c === '/' && n === '*') { mode = 'block'; i++; continue; }\n    if (c === \"'\" || c === '\"') { mode = c; continue; }\n    if (c === '`') { modes.push('code'); mode = '`'; continue; }\n    if (c === ';') { last = i + 1; continue; }\n    if (c === '{') {\n      const head = text.slice(last, i).replace(/\\s+/g, ' ').trim();\n      const name = functionName(head, stack);\n      stack.push(name ? { kind: 'fn', name, start: i } : { kind: 'block' });\n      last = i + 1;\n    } else if (c === '}') {\n      const top = stack.pop();\n      if (top?.kind === 'tpl') { mode = modes.pop() ?? '`'; continue; }\n      if (top?.kind === 'fn') ranges.push({ name: top.name, start: top.start, end: i });\n      last = i + 1;\n    }\n  }\n  return ranges;\n}\n\nfunction functionName(head, stack) {\n  const outer = [...stack].reverse().find((s) => s.kind === 'fn')?.name;\n  let m;\n  if ((m = /function\\s*\\*?\\s*([\\w$]+)\\s*\\([^)]*\\)$/.exec(head))) return m[1];\n  if ((m = /addEventListener\\(\\s*['\"]([\\w-]+)['\"]\\s*,\\s*(?:async\\s*)?(?:\\([^)]*\\)|[\\w$]+)\\s*=>$/.exec(head)) || (m = /addEventListener\\(\\s*['\"]([\\w-]+)['\"]\\s*,\\s*(?:async\\s*)?function\\b[^(]*\\([^)]*\\)$/.exec(head))) return `${m[1]} listener${outer ? ` in ${outer}` : ''}`;\n  if ((m = /([\\w$.]+)\\s*[:=]\\s*(?:async\\s*)?(?:function\\b[^(]*\\([^)]*\\)|\\([^)]*\\)\\s*=>|[\\w$]+\\s*=>)$/.exec(head))) return m[1];\n  if ((m = /^(?:async\\s+|static\\s+|get\\s+|set\\s+)*([\\w$]+)\\s*\\([^)]*\\)$/.exec(head)) && !/^(if|for|while|switch|catch|function|with|return)$/.test(m[1])) return m[1];\n  if (/=>$|function\\b[^(]*\\([^)]*\\)$/.test(head)) {\n    const call = /([\\w$]+)\\(\\s*[^()]*(?:\\([^)]*\\))?\\s*=>$/.exec(head) ?? /([\\w$]+)\\((?:[^()]*,)?\\s*(?:async\\s*)?(?:\\([^)]*\\)|[\\w$]+)\\s*=>$/.exec(head);\n    return call ? `${call[1]} callback${outer ? ` in ${outer}` : ''}` : `anonymous${outer ? ` in ${outer}` : ''}`;\n  }\n  return null;\n}\n\nconst nameAt = (ranges, index) => ranges.filter((r) => r.start <= index && index <= r.end).sort((a, b) => a.start - b.start).at(-1)?.name ?? '(top level)';\n\nfunction usesAfter(rest) {\n  if (/^\\s*\\.(addEventListener|on[a-z]+\\s*=)/.test(rest)) return 'listens';\n  if (/^\\s*\\.(textContent|innerText|value|hidden|checked|disabled|src|href|alt|open)\\s*=[^=]|^\\s*\\.(append|prepend|replaceChildren|replaceWith|remove|setAttribute|removeAttribute|toggleAttribute|showModal|show|close|focus|reset|style\\.setProperty)\\b/.test(rest)) return 'writes';\n  return 'reads';\n}\n\n// ------------------------------------------------------------------ the check\n\nexport function check(manifestPath, { write = false } = {}) {\n  const base = dirname(resolve(manifestPath));\n  const rel = (abs) => relative(base, abs).split('\\\\').join('/');\n  const problems = [];\n  const read = (abs) => readFileSync(abs, 'utf8');\n  let manifest;\n  try { manifest = JSON.parse(read(manifestPath)); } catch (e) { return { problems: [`builder.json: cannot read (${e.message})`], map: null }; }\n\n  // The manifest: every path it names exists.\n  for (const key of ['kit', 'pages', 'hooks', 'tokens', 'styleLayer', 'preview', 'gallery']) if (manifest[key] === undefined) problems.push(`builder.json: \"${key}\" is missing`);\n  if (problems.length) return { problems, map: null };\n  const at = (p) => join(base, p);\n  for (const p of [manifest.tokens, manifest.styleLayer, manifest.preview.page, manifest.gallery, ...manifest.pages.map((x) => x.file)]) if (!existsSync(at(p))) problems.push(`builder.json: ${p} does not exist`);\n  if (problems.length) return { problems, map: null };\n  const tokensFile = at(manifest.tokens);\n  const layerFile = at(manifest.styleLayer);\n  const helpers = manifest.scripts?.hookCalls ?? { hook: 0, hooks: 0, fromTemplate: 0, part: 1 };\n  const tokensModule = manifest.tokensModule ? resolve(at(manifest.tokensModule)) : null;\n  const fillCalls = manifest.scripts?.fillCalls ?? ['fill'];\n  const ignore = (manifest.scripts?.ignore ?? ['/vendor/', '/node_modules/']).map((x) => x.toLowerCase());\n  const helperFiles = new Set((manifest.scripts?.helperFiles ?? []).map((f) => resolve(at(f))));\n  const allowHosts = manifest.links?.allowHosts ?? [];\n  const blockLinks = (manifest.links?.block ?? []).map((b) => ({ re: new RegExp(b.pattern, 'i'), why: b.why }));\n\n  const pageFiles = [...manifest.pages.map((p) => p.file), manifest.preview.page, manifest.gallery];\n  const pages = pageFiles.map((f) => ({ ...parsePage(f, read(at(f))), abs: at(f) }));\n\n  // ---- markup\n  const where = new Map(); // hook -> [{ page, el }]\n  const nowhere = []; // links without a target; fine only when a script sets the href\n  for (const p of pages) {\n    problems.push(...p.problems);\n    const seen = new Map();\n    for (const el of p.elements) {\n      if (el.attrs.style !== undefined) problems.push(`${p.file}:${el.line}: <${el.tag}> has an inline style (put the rule in a stylesheet, keyed by its hook)`);\n      if (el.tag === 'style') problems.push(`${p.file}:${el.line}: <style> in a page (styles live in stylesheets)`);\n      if (!el.inBody) continue;\n      if (el.tag === 'a') {\n        const href = el.attrs.href;\n        if (href === undefined || href === '' || href === '#' || /^javascript:/i.test(href)) nowhere.push({ hook: el.attrs['data-hook'], text: `${p.file}:${el.line}: a link that goes nowhere (use a <button> for an action, or have a script set its href)` });\n        else if (/^(https?:)?\\/\\//i.test(href)) {\n          const host = new URL(href, 'https://site.invalid/').hostname.replace(/^www\\./, '');\n          const blocked = blockLinks.find((b) => b.re.test(href));\n          if (blocked) problems.push(`${p.file}:${el.line}: link ${href} is not allowed (${blocked.why})`);\n          else if (!allowHosts.some((h) => host === h || host.endsWith(`.${h}`))) problems.push(`${p.file}:${el.line}: link to ${host} leaves the site (allowed outside hosts: ${allowHosts.join(', ') || 'none'})`);\n        }\n      }\n      const hook = el.attrs['data-hook'];\n      if (hook === undefined) {\n        if (!NO_HOOK.has(el.tag)) problems.push(`${p.file}:${el.line}: <${el.tag}> has no data-hook`);\n        continue;\n      }\n      if (!HOOK_NAME.test(hook)) problems.push(`${p.file}:${el.line}: hook \"${hook}\" is not lower-case words joined by dashes`);\n      else if (VAGUE.test(hook)) problems.push(`${p.file}:${el.line}: hook \"${hook}\" says nothing about what it is`);\n      if (el.template === null && seen.has(hook)) problems.push(`${p.file}:${el.line}: duplicate hook \"${hook}\" (also line ${seen.get(hook)})`);\n      if (el.template !== null && p.elements.some((o) => o !== el && o.template === el.template && o.attrs['data-hook'] === hook)) problems.push(`${p.file}:${el.line}: duplicate hook \"${hook}\" inside ${el.template}`);\n      if (el.template === null) seen.set(hook, el.line);\n      if (el.tag === 'template') {\n        if (!hook.startsWith('template-')) problems.push(`${p.file}:${el.line}: template hook \"${hook}\" must start with \"template-\"`);\n        const inside = p.elements.filter((e) => e.parent === el);\n        if (inside.length !== 1) problems.push(`${p.file}:${el.line}: ${hook} must hold exactly one element (it holds ${inside.length})`);\n      } else if (hook.startsWith('template-')) problems.push(`${p.file}:${el.line}: only a <template> hook starts with \"template-\"`);\n      if (!where.has(hook)) where.set(hook, []);\n      where.get(hook).push({ page: p.file, el });\n    }\n    // Stylesheets: tokens first, style layer last.\n    const sheets = p.styles.filter((s) => s.href).map((s) => resolve(dirname(p.abs), s.href));\n    if (sheets[0] !== resolve(tokensFile)) problems.push(`${p.file}: ${manifest.tokens} must be the first stylesheet`);\n    if (sheets.at(-1) !== resolve(layerFile)) problems.push(`${p.file}: ${manifest.styleLayer} must be the last stylesheet`);\n    for (const s of p.scripts) if (s.inline && s.type !== 'application/json') problems.push(`${p.file}:${s.line}: inline script (move it to a .js file)`);\n    p.sheets = sheets;\n  }\n  for (const [hook, list] of where) {\n    if (new Set(list.map((w) => kindOf(w.el))).size > 1) problems.push(`hook \"${hook}\" is a different element on different pages: ${list.map((w) => `${w.page} ${kindOf(w.el)}`).join(', ')}`);\n  }\n\n  // ---- stylesheets\n  const sheetFiles = [...new Set(pages.flatMap((p) => p.sheets))].filter(existsSync);\n  const tokens = new Map(); // name -> default\n  const tokenUsers = new Map(); // name -> Set(hook)\n  const hookTokens = new Map(); // hook -> Set(token)\n  const usedVars = [];\n  const declared = new Set(); // custom properties any stylesheet declares (run-time values a script sets)\n  for (const abs of sheetFiles) {\n    const file = rel(abs);\n    const colorsAllowed = abs === resolve(tokensFile) || abs === resolve(layerFile);\n    for (const r of cssRules(read(abs))) {\n      if (r.selector.startsWith('@')) continue;\n      const bare = r.selector.replace(/\\[[^\\]]*\\]/g, '').replace(/\\([^)]*\\)/g, '');\n      if (/[.#][a-zA-Z_-]/.test(bare)) problems.push(`${file}:${r.line}: selector \"${r.selector}\" uses a class or id (key rules by [data-hook=\"...\"])`);\n      const hooks = selectorReach(r.selector, where.keys());\n      for (const d of r.decls) {\n        if (d.prop.startsWith('--')) {\n          declared.add(d.prop);\n          if (abs === resolve(tokensFile) && !tokens.has(d.prop)) tokens.set(d.prop, d.value);\n          if (abs === resolve(layerFile) && !tokens.has(d.prop)) tokens.set(d.prop, null);\n          if (!colorsAllowed && COLOR.test(d.value)) problems.push(`${file}:${d.line}: colour \"${d.value}\" outside ${manifest.tokens} (name it there and use var(${d.prop}))`);\n        } else if (COLOR.test(d.value.replace(/var\\([^)]*\\)/g, ''))) {\n          problems.push(`${file}:${d.line}: colour in \"${d.prop}: ${d.value}\" is not a token (use var(--...) from ${manifest.tokens})`);\n        }\n        for (const v of varsIn(d.value)) {\n          usedVars.push({ v, where: `${file}:${d.line}` });\n          for (const h of hooks) {\n            if (!tokenUsers.has(v)) tokenUsers.set(v, new Set());\n            tokenUsers.get(v).add(h);\n            if (!hookTokens.has(h)) hookTokens.set(h, new Set());\n            hookTokens.get(h).add(v);\n          }\n        }\n      }\n      for (const h of selectorHooks(r.selector)) if (!where.has(h)) problems.push(`${file}:${r.line}: rule for hook \"${h}\", which no page has`);\n    }\n  }\n  for (const u of usedVars) if (!tokens.has(u.v) && !declared.has(u.v)) problems.push(`${u.where}: var(${u.v}) is not defined in ${manifest.tokens} or any stylesheet`);\n\n  // ---- scripts\n  const scripts = new Map(); // abs -> text\n  const pageScripts = new Map();\n  const load = (abs, into) => {\n    if (into.has(abs) || !existsSync(abs)) return;\n    into.add(abs);\n    if (!scripts.has(abs)) scripts.set(abs, read(abs));\n    for (const m of scripts.get(abs).matchAll(/(?:\\bfrom\\s*|\\bimport\\s*\\(\\s*|^\\s*import\\s+)['\"](\\.{1,2}\\/[^'\"]+\\.m?js)['\"]/gm)) load(resolve(dirname(abs), m[1]), into);\n  };\n  for (const p of pages) {\n    const set = new Set();\n    for (const s of p.scripts) if (s.src && !/^(https?:)?\\/\\//.test(s.src)) {\n      const abs = resolve(dirname(p.abs), s.src);\n      if (!existsSync(abs)) problems.push(`${p.file}:${s.line}: script ${s.src} does not exist`);\n      load(abs, set);\n    }\n    pageScripts.set(p.file, set);\n  }\n  const refs = new Map(); // hook -> [{file,line,function,uses}]\n  const addRef = (hook, r) => { if (!refs.has(hook)) refs.set(hook, []); refs.get(hook).push(r); };\n  const callRe = new RegExp(`(?<![\\\\w$.])(?<!function\\\\s)(${Object.keys(helpers).map((h) => h.replace(/\\$/g, '\\\\$')).join('|')})\\\\s*\\\\(`, 'g');\n  for (const [abs, text] of scripts) {\n    const file = rel(abs);\n    if (abs === tokensModule || helperFiles.has(abs) || ignore.some((x) => abs.toLowerCase().includes(x))) continue;\n    const ranges = functionRanges(text);\n    const lineOfIndex = (idx) => text.slice(0, idx).split('\\n').length;\n    // fill(copy, { 'hook-name': value, ... }): every quoted key is a hook the call writes.\n    for (const m of text.matchAll(new RegExp(`(?<![\\\\w$.])(?:${fillCalls.join('|')})\\\\s*\\\\(`, 'g'))) {\n      let depth = 0;\n      let end = m.index + m[0].length;\n      for (; end < text.length; end++) {\n        const c = text[end];\n        if (c === '(' || c === '{' || c === '[') depth++;\n        else if (c === ')' || c === '}' || c === ']') { if (depth === 0) break; depth--; }\n        else if (c === \"'\" || c === '\"' || c === '`') { const e = text.indexOf(c, end + 1); if (e === -1) break; end = e; }\n      }\n      const call = text.slice(m.index, end).replace(/^(\\s*)\\/\\/.*$/gm, (c) => c.replace(/[^\\n]/g, ' ')); // whole-line comments blanked\n      for (const k of call.matchAll(/(?<=[{,]\\s*)(['\"])([a-z][a-z0-9-]*)\\1\\s*:/g)) {\n        const idx = m.index + k.index;\n        addRef(k[2], { file, line: lineOfIndex(idx), function: nameAt(ranges, idx), uses: 'writes' });\n      }\n    }\n    const held = new Map(); // variable name -> { hooks, end } for `const a = hook('x')`, followed to the end of its function\n    const lines = text.split('\\n');\n    const lineStart = [];\n    lines.reduce((pos, l, i) => ((lineStart[i] = pos), pos + l.length + 1), 0);\n    lines.forEach((line, i) => {\n      const code = line.replace(/\\/\\/.*$/, '');\n      const fn = nameAt(ranges, lineStart[i]);\n      const where_ = { file, line: i + 1, function: fn };\n      if (/\\.style\\b(?!\\s*\\.\\s*(setProperty|getPropertyValue|removeProperty)\\(\\s*['\"`]--)|setAttribute\\(\\s*['\"]style/.test(code)) problems.push(`${file}:${i + 1}: script sets an inline style (set a CSS variable with style.setProperty('--name', ...) or a data- attribute the stylesheet keys on)`);\n      if (/\\bcreateElement(NS)?\\s*\\(|\\.(innerHTML|outerHTML)\\s*=|insertAdjacentHTML\\s*\\(/.test(code)) problems.push(`${file}:${i + 1}: script builds markup (declare it in a <template data-hook=\"template-...\"> and clone it)`);\n      if (/(['\"`])\\s*(#[0-9a-fA-F]{3,8}|(rgba?|hsla?|oklch)\\([^'\"`]*\\))\\s*\\1/.test(code)) problems.push(`${file}:${i + 1}: colour in a script (read it from a token with getComputedStyle)`);\n      const note = /\\/\\/\\s*hooks:\\s*(.+)$/.exec(line);\n      const noted = note ? note[1].split(/,\\s*(?![^{]*\\})/).flatMap((x) => expandBraces(x.trim())).filter(Boolean) : null;\n      if (noted) for (const h of noted) addRef(h, { ...where_, uses: 'reads' });\n      // Uses of an element held in a variable: a.href = ..., a.addEventListener(...)\n      for (const [name, v] of held) {\n        if (lineStart[i] > v.end) { held.delete(name); continue; }\n        if (v.line === i) continue;\n        const use = new RegExp(`(?<![\\\\w$.])${name.replace(/\\$/g, '\\\\$')}(?=\\\\s*\\\\.)`).exec(code);\n        if (use) { const u = usesAfter(code.slice(use.index + name.length)); if (u !== 'reads') for (const h of v.hooks) addRef(h, { ...where_, uses: u }); }\n      }\n      const holdAs = (hooksHeld, at) => {\n        const decl = /(?:const|let|var)\\s+([\\w$]+)\\s*=\\s*$/.exec(code.slice(0, at));\n        if (decl) held.set(decl[1], { hooks: hooksHeld, line: i, end: ranges.filter((r) => r.start <= lineStart[i] && lineStart[i] <= r.end).sort((a, b) => a.start - b.start).at(-1)?.end ?? text.length });\n      };\n      for (const m of code.matchAll(callRe)) {\n        const argPos = helpers[m[1]];\n        let j = m.index + m[0].length;\n        let depth = 0;\n        let arg = 0;\n        let start = j;\n        let found = null;\n        for (; j < code.length; j++) {\n          const c = code[j];\n          if ('([{'.includes(c)) depth++;\n          else if (')]}'.includes(c)) { if (depth === 0) break; depth--; }\n          else if (c === ',' && depth === 0) { if (arg === argPos) break; arg++; start = j + 1; }\n          else if ((c === \"'\" || c === '\"' || c === '`') && depth === 0) { const e = code.indexOf(c, j + 1); if (e === -1) break; j = e; }\n        }\n        if (arg === argPos) found = code.slice(start, j).trim();\n        if (found === null || found === '' || /^\\s*\\{/.test(code.slice(j + 1))) continue; // empty, or a method's own definition\n        const lit = /^(['\"`])([^'\"`$]*)\\1$/.exec(found);\n        const either = /\\?\\s*(['\"])([^'\"]*)\\1\\s*:\\s*(['\"])([^'\"]*)\\3$/.exec(found);\n        const close = code.indexOf(')', j);\n        const uses = usesAfter(code.slice(close + 1));\n        if (lit) addRef(lit[2], { ...where_, uses });\n        else if (either) for (const h of [either[2], either[4]]) addRef(h, { ...where_, uses });\n        const names = lit ? [lit[2]] : either ? [either[2], either[4]] : noted;\n        if (names) holdAs(names, m.index);\n        else if (!noted) problems.push(`${file}:${i + 1}: ${m[1]}(${found}) builds a hook name at run time (add a \"// hooks: name-{a,b}\" comment listing every name)`);\n      }\n      for (const m of code.matchAll(/\\[data-hook=\"([a-z0-9-]+)\"\\]/g)) addRef(m[1], { ...where_, uses: usesAfter(code.slice(code.indexOf(')', m.index) + 1)) });\n    });\n  }\n  for (const n of nowhere) if (!(refs.get(n.hook) ?? []).some((r) => r.uses === 'writes')) problems.push(n.text);\n  for (const [hook, list] of refs) if (!where.has(hook)) for (const r of list) problems.push(`${r.file}:${r.line}: script uses hook \"${hook}\", which no page has`);\n\n  // ---- preview screens: each is named in its page's scripts\n  for (const s of manifest.preview.screens ?? []) {\n    const page = pages.find((p) => p.file === s.page);\n    if (!page) { problems.push(`builder.json: screen \"${s.name}\" is on ${s.page}, which is not a listed page`); continue; }\n    const named = [...(pageScripts.get(s.page) ?? [])].some((abs) => new RegExp(`['\"]${s.name}['\"]\\\\s*:|\\\\b${s.name.replace(/-/g, '\\\\-')}\\\\s*:`).test(scripts.get(abs)));\n    if (!/^[a-z0-9-]+$/.test(s.name) || !named) problems.push(`builder.json: screen \"${s.name}\" is not declared in the scripts of ${s.page} (screens({ '${s.name}': () => ... }))`);\n  }\n\n  // ---- the map\n  const hooks = {};\n  for (const [hook, list] of where) {\n    const el = list[0].el;\n    hooks[hook] = {\n      pages: [...new Set(list.map((w) => w.page))].sort(),\n      element: kindOf(el),\n      parent: parentHook(el),\n      scriptBuilt: el.template !== null,\n      template: el.template,\n      tokens: [...(hookTokens.get(hook) ?? [])].sort(),\n      references: (refs.get(hook) ?? []).sort((a, b) => (a.file + String(a.line).padStart(6, '0') < b.file + String(b.line).padStart(6, '0') ? -1 : 1)),\n    };\n  }\n  const map = {\n    about: 'Made by kit-check from the pages, stylesheets and scripts (npm run kit:hooks). Do not edit by hand.',\n    kit: manifest.kit,\n    pages: sortObj(Object.fromEntries(pages.map((p) => [p.file, { stylesheets: p.sheets.map(rel), scripts: [...pageScripts.get(p.file)].map(rel).sort() }]))),\n    tokens: sortObj(Object.fromEntries([...tokens].map(([t, d]) => [t, { default: d, usedBy: [...(tokenUsers.get(t) ?? [])].sort() }]))),\n    hooks: sortObj(hooks),\n  };\n  const json = `${JSON.stringify(map, null, 2)}\\n`;\n  if (tokensModule) {\n    const entries = [...tokens].filter(([, d]) => d !== null).map(([t, d]) => `  ${JSON.stringify(t)}: ${JSON.stringify(d)},`);\n    const js = `// Made by kit-check from ${manifest.tokens} (npm run kit:hooks). Do not edit by hand.\\n// Every token's value, for scripts that need one outside a styled page (tests, pictures drawn as data).\\nexport const TOKENS = {\\n${entries.join('\\n')}\\n};\\n`;\n    if (write) writeFileSync(tokensModule, js);\n    else if (!existsSync(tokensModule) || read(tokensModule) !== js) problems.push(`${manifest.tokensModule} is stale: it does not match ${manifest.tokens} (run npm run kit:hooks and commit it)`);\n  }\n  const hooksFile = at(manifest.hooks);\n  if (write) writeFileSync(hooksFile, json);\n  else if (!existsSync(hooksFile)) problems.push(`${manifest.hooks} is missing (run npm run kit:hooks)`);\n  else if (read(hooksFile) !== json) problems.push(`${manifest.hooks} is stale: it does not match the code (run npm run kit:hooks and commit it)`);\n  return { problems, map };\n}\n\n// ------------------------------------------------------------------ command line\n\nif (import.meta.url === new URL(`file://${resolve(process.argv[1] ?? '')}`).href) {\n  const args = process.argv.slice(2);\n  const manifestPath = args.find((a) => !a.startsWith('--')) ?? 'builder.json';\n  const { problems, map } = check(manifestPath, { write: args.includes('--write') });\n  for (const p of problems) console.log(`  ✗ ${p}`);\n  const n = map ? Object.keys(map.hooks).length : 0;\n  const pagesN = map ? Object.keys(map.pages).length : 0;\n  console.log(problems.length ? `kit:check failed: ${problems.length} problem(s)` : `kit:check passed: ${pagesN} pages, ${n} hooks, ${map ? Object.keys(map.tokens).length : 0} tokens`);\n  process.exit(problems.length ? 1 : 0);\n}\n",
  "tools/kit-diff.mjs": "#!/usr/bin/env node\n// Compares this branch with the branch it will merge into, for the two kinds of change a\n// builder-ready repo gets. No dependencies besides git.\n//\n//   node tools/kit-diff.mjs [builder.json] --base <ref> [--style-only] [--allow-removed] [--changes <file>]\n//   npm run kit:diff -- --base origin/main\n//   npm run kit:diff -- --base origin/main --style-only\n//\n// A code change (the default): no hook the base branch had may disappear, because the design's\n// rules for it would silently stop applying. Lists added and removed hooks, and hooks whose element\n// kind changed. --allow-removed accepts removals the pull request explains (say which, so J can move\n// their style).\n// A hook J deleted in the builder is listed as removed in design/HOOK-CHANGES.json, which the\n// builder's design branch carries (at the repository's root, or next to builder.json). A code\n// change that drops a hook listed there passes; dropping any other hook still fails. --changes\n// names that file when it lives elsewhere.\n// A style change from the builder (--style-only): only the design's files may change (the style\n// layer, the tokens, the files made from them, builder.json's \"styleAssets\" folder if it has\n// one, and the design record under design/), no token may disappear, and no hook may change at all.\n// Both also run the full contract check.\nimport { execFileSync } from 'node:child_process';\nimport { existsSync, readFileSync } from 'node:fs';\nimport { dirname, resolve } from 'node:path';\nimport { check } from './kit-check.mjs';\n\nconst git = (cwd, ...args) => execFileSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });\n\n// The hooks the builder's design deleted on purpose, from design/HOOK-CHANGES.json.\nexport function designRemoved(dir, changesPath) {\n  let root = dir;\n  try { root = git(dir, 'rev-parse', '--show-toplevel').trim(); } catch { /* not a repository */ }\n  const at = changesPath ? [resolve(changesPath)] : [resolve(root, 'design/HOOK-CHANGES.json'), resolve(dir, 'design/HOOK-CHANGES.json')];\n  const file = at.find((f) => existsSync(f));\n  if (!file) return { file: null, hooks: [] };\n  const json = JSON.parse(readFileSync(file, 'utf8'));\n  return { file, hooks: (json.removed ?? []).map((r) => (typeof r === 'string' ? r : r?.hook)).filter(Boolean) };\n}\n\nexport function diff(manifestPath, { base, styleOnly = false, allowRemoved = false, changes = null }) {\n  const dir = dirname(resolve(manifestPath));\n  const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));\n  const problems = [];\n  let from = base;\n  try { from = git(dir, 'merge-base', base, 'HEAD').trim(); } catch { /* not a branch of HEAD; compare with the ref itself */ }\n\n  const { problems: contract, map } = check(manifestPath);\n  problems.push(...contract);\n  let before = { hooks: {}, tokens: {} };\n  try { before = JSON.parse(git(dir, 'show', `${from}:./${manifest.hooks}`)); } catch { /* new site: nothing to lose */ }\n  const now = map ?? JSON.parse(readFileSync(resolve(dir, manifest.hooks), 'utf8'));\n\n  const removed = Object.keys(before.hooks).filter((h) => !now.hooks[h]);\n  const added = Object.keys(now.hooks).filter((h) => !before.hooks[h]);\n  const changed = Object.keys(now.hooks).filter((h) => before.hooks[h] && before.hooks[h].element !== now.hooks[h].element);\n  const lostTokens = Object.keys(before.tokens ?? {}).filter((t) => !(now.tokens ?? {})[t]);\n\n  const listed = new Set(styleOnly ? [] : designRemoved(dir, changes).hooks);\n  if (styleOnly) {\n    const owned = [manifest.styleLayer, manifest.tokens, manifest.tokensModule, manifest.hooks].filter(Boolean);\n    const assets = manifest.styleAssets ? `${manifest.styleAssets.replace(/\\/$/, '')}/` : null;\n    const files = git(dir, 'diff', '--relative', '--name-only', from).split('\\n').filter(Boolean);\n    files.push(...git(dir, 'ls-files', '--others', '--exclude-standard').split('\\n').filter(Boolean));\n    /* The builder's design record (design/record.json, DESIGN-RECORD.md) and the rest of design/ ride with a style change. */\n    const design = (f) => f.startsWith('design/') || f.includes('/design/');\n    for (const f of files) if (!owned.includes(f) && !(assets && f.startsWith(assets)) && !design(f)) problems.push(`${f} changed, but a style change may only touch ${[...owned, ...(assets ? [assets] : [])].join(', ')}`);\n    for (const h of [...removed, ...added]) problems.push(`hook \"${h}\" was ${removed.includes(h) ? 'removed' : 'added'} (a style change never changes hooks)`);\n    for (const t of lostTokens) problems.push(`token ${t} was removed (a style change may change a token's value, not drop it)`);\n  } else {\n    if (!allowRemoved) for (const h of removed.filter((x) => !listed.has(x))) problems.push(`hook \"${h}\" was removed; the design's rules for it would stop applying (keep it, or pass --allow-removed and say so in the pull request)`);\n  }\n  const deleted = removed.filter((h) => listed.has(h));\n  return { problems, removed, added, changed, lostTokens, from, deleted };\n}\n\nif (import.meta.url === new URL(`file://${resolve(process.argv[1] ?? '')}`).href) {\n  const args = process.argv.slice(2);\n  const at = args.indexOf('--base');\n  const base = at >= 0 ? args[at + 1] : undefined;\n  const manifestPath = args.find((a, i) => !a.startsWith('--') && i !== at + 1 && args[i - 1] !== '--changes') ?? 'builder.json';\n  if (!base) {\n    console.log('usage: npm run kit:diff -- --base <branch or commit> [--style-only] [--allow-removed]');\n    process.exit(2);\n  }\n  const styleOnly = args.includes('--style-only');\n  const ci = args.indexOf('--changes');\n  const r = diff(manifestPath, { base, styleOnly, allowRemoved: args.includes('--allow-removed'), changes: ci >= 0 ? args[ci + 1] : null });\n  const list = (xs) => (xs.length ? xs.join(', ') : 'none');\n  console.log(`Compared with ${base}: hooks added: ${list(r.added)}; removed: ${list(r.removed)}; element changed: ${list(r.changed)}; tokens removed: ${list(r.lostTokens)}.`);\n  if (r.deleted.length) console.log(`Removed as the design asked (design/HOOK-CHANGES.json): ${list(r.deleted)}.`);\n  for (const p of r.problems) console.log(`  ✗ ${p}`);\n  const kind = styleOnly ? 'style change' : 'code change';\n  console.log(r.problems.length ? `kit:diff failed: ${r.problems.length} problem(s) in this ${kind}` : `kit:diff passed: this ${kind} keeps every hook the design uses`);\n  process.exit(r.problems.length ? 1 : 0);\n}\n",
  ".github/workflows/kit-check.yml": "# Runs the builder contract check and the kit's own tests on every push and pull request, and on a\n# pull request also kit:diff against the branch it merges into: a code change may not drop a hook\n# the design uses; a branch named style/... (the builder's design coming back) may change only the\n# style layer and token values. See PIPELINE.md.\n# Active once this kit/ folder is a repo of its own (or copied to a repo root). Inside a bigger\n# repo, copy this file to that repo's .github/workflows/ and set working-directory to the folder\n# that holds builder.json.\nname: kit-check\non:\n  push:\n  pull_request:\njobs:\n  kit-check:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 22\n      - run: npm run kit:check\n      - run: npm test\n      - if: github.event_name == 'pull_request' && !startsWith(github.head_ref, 'style/')\n        run: npm run kit:diff -- --base origin/${{ github.base_ref }}\n      - if: github.event_name == 'pull_request' && startsWith(github.head_ref, 'style/')\n        run: npm run kit:diff -- --base origin/${{ github.base_ref }} --style-only\n",
  "starter/js/hooks.js": "// The only way scripts reach the page: by data-hook. kit-check reads every call to these helpers\n// (the hook name must be a plain string, or the line carries a \"// hooks: a-{b,c}\" comment).\n\n/** The element with this hook (inside root). Throws if it is missing, so a renamed hook fails loudly. */\nexport function hook(name, root = document) {\n  const found = root.querySelector(`[data-hook=\"${name}\"]`);\n  if (!found) throw new Error(`no element with data-hook=\"${name}\"`);\n  return found;\n}\n\n/** Every element with this hook (inside root). */\nexport function hooks(name, root = document) {\n  return [...root.querySelectorAll(`[data-hook=\"${name}\"]`)];\n}\n\n/** A copy of the one element inside <template data-hook=\"name\">. Scripts never build markup any other way. */\nexport function fromTemplate(name) {\n  const template = hook(name);\n  return template.content.firstElementChild.cloneNode(true);\n}\n\n/** The part with this hook inside a copy made by fromTemplate (or the copy itself). */\nexport function part(copy, name) {\n  return copy.dataset.hook === name ? copy : hook(name, copy);\n}\n\n/** The page's search parameters: ?still=1 freezes motion, &screen=<name> picks a preview state. */\nexport const params = new URLSearchParams(location.search);\nexport const still = params.get('still') === '1';\nif (still) document.documentElement.toggleAttribute('data-still', true);\n\n/**\n * Declares the screens (states) a page can show, by name, as listed in builder.json. With\n * ?screen=<name> the matching one runs after the page is set up; otherwise the first runs.\n */\nexport function screens(table) {\n  const name = params.get('screen') ?? Object.keys(table)[0];\n  (table[name] ?? Object.values(table)[0])();\n}\n",
  "starter/js/preview.js": "// The preview page: every screen listed in builder.json, each frozen (?still=1) in its own frame.\nimport { fromTemplate, hook, part } from './hooks.js';\n\nasync function draw() {\n  const manifest = await (await fetch('../builder.json')).json();\n  const root = new URL('../', location.href);\n  const copies = manifest.preview.screens.map((screen) => {\n    const copy = fromTemplate('template-preview-screen');\n    part(copy, 'preview-caption').textContent = screen.name;\n    part(copy, 'preview-frame').src = new URL(`${screen.page}?still=1&screen=${screen.name}`, root).href;\n    return copy;\n  });\n  hook('preview-screens').replaceChildren(...copies);\n}\n\ndraw();\n",
};
